<?php
$title='Papierkorb';
$labels=['dutybook'=>'Dienstbuch','special_reports'=>'Sonderbericht','valuables'=>'Wertsachen','house_bans'=>'Hausverbote'];
$deletePermissions=['dutybook'=>'dutybook.delete','special_reports'=>'special_reports.delete','valuables'=>'valuables.delete','house_bans'=>'house_bans.delete'];
?>
<div class="page-header"><div><p class="eyebrow">Administration</p><h1>Zentraler Papierkorb</h1><p>Gelöschte Datensätze bleiben unbegrenzt erhalten, bis ein Administrator aktiv wiederherstellt oder endgültig löscht.</p></div></div>
<div class="panel"><form method="get" action="<?= e(url('admin/trash')) ?>" class="filterbar"><input type="search" name="q" value="<?= e($search) ?>" placeholder="Volltextsuche im Papierkorb"><button class="button secondary" type="submit">Suchen</button></form>
<div class="table-wrap"><table><thead><tr><th>Gelöscht</th><th>Modul</th><th>Zusammenfassung</th><th>Standort</th><th>Benutzer</th><th>Aktionen</th></tr></thead><tbody><?php foreach($entries as $x):?><tr><td><?= e(format_datetime($x['deleted_at'])) ?></td><td><?= e($labels[$x['module']]??$x['module']) ?></td><td><?= e($x['summary']) ?></td><td><?= e($x['location_name']??'–') ?></td><td><?= e($x['deleted_by_name']??'–') ?></td><td><?php $allowed=isset($deletePermissions[$x['module']])&&can($deletePermissions[$x['module']]);if($allowed):?><div class="inline-actions"><form method="post" action="<?= e(url('admin/trash/'.$x['id'].'/restore')) ?>"><?= csrf_field() ?><button class="button secondary compact" type="submit">Wiederherstellen</button></form><form method="post" action="<?= e(url('admin/trash/'.$x['id'].'/delete')) ?>" data-confirm="Datensatz wirklich endgültig löschen? Diese Aktion kann nicht rückgängig gemacht werden."><?= csrf_field() ?><button class="button danger compact" type="submit">Endgültig löschen</button></form></div><?php else:?><span class="muted">Kein Modul-Löschrecht</span><?php endif;?></td></tr><?php endforeach;?><?php if($entries===[]):?><tr><td colspan="6" class="empty">Papierkorb ist leer.</td></tr><?php endif;?></tbody></table></div></div>
